package com.meterflow.invoicing;
import jakarta.persistence.*; import java.util.*; import java.math.*; import java.time.*;
@Entity @Table(name="invoices",uniqueConstraints=@UniqueConstraint(name="uk_invoice_customer_period",columnNames={"customer_id","period"})) public class Invoice {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="customer_id",nullable=false) private String customerId; @Column(nullable=false) private String period; @Column(nullable=false) private String status="DRAFT"; @Column(nullable=false) private String currency; @Column(nullable=false,precision=18,scale=2) private BigDecimal subtotal; @Column(nullable=false,precision=18,scale=2) private BigDecimal tax; @Column(nullable=false,precision=18,scale=2) private BigDecimal total; @Column(nullable=false) private Instant createdAt=Instant.now();
 protected Invoice(){} public Invoice(String c,String p,String currency,BigDecimal sub,BigDecimal tax){customerId=c;period=p;this.currency=currency;subtotal=sub;this.tax=tax;total=sub.add(tax);} public UUID getId(){return id;} public String getCustomerId(){return customerId;} public String getPeriod(){return period;} public String getStatus(){return status;} public String getCurrency(){return currency;} public BigDecimal getSubtotal(){return subtotal;} public BigDecimal getTax(){return tax;} public BigDecimal getTotal(){return total;} public Instant getCreatedAt(){return createdAt;} public void markPaid(){if(!"FINALISED".equals(status))throw new IllegalStateException("Only finalised invoices can be paid");status="PAID";} public void finalise(){if(!"DRAFT".equals(status))throw new IllegalStateException("Only draft invoices can be finalised");status="FINALISED";}
}
